/bin/bash -lc '
set -e
H="$HORIZON_GIT"
BASE=d80ceb90affb7427f7fa4607fcce5f7558ddd961
SNAP=52ba623e36642971c1649e755f84189e14372e90
T=$(mktemp -d)
trap '"'rm -rf \""'$T"'"' EXIT
for tagrev in \"base:"'$BASE" "head:$SNAP"; do
  tag=${tagrev%%:*}; rev=${tagrev#*:}
  mkdir "$T/$tag"
  env -u GIT_INDEX_FILE "$H" archive --format=tar "$rev" -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian | tar -xf - -C "$T/$tag"
done
python - "$T" <<'"'PY'
import pathlib,sys
from archon_horizon.search.index import extract_declarations
T=pathlib.Path(sys.argv[1]); sub=\"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian\"
def split_top(s):
 d=0;q=False;e=False
 for i,c in enumerate(s):
  if q:
   if e:e=False
   elif c==\"\\\\\":e=True
   elif c=='\"':q=False
   continue
  if c=='\"':q=True;continue
  if c in \"([{\":d+=1
  elif c in \")]}\":d=max(0,d-1)
  elif c==\":\" and d==0 and not (i+1<len(s) and s[i+1]==\"=\"):return s[:i],s[i+1:]
 return s,\"\"
def load(tag):
 out={}
 for p in (T/tag/sub).rglob(\"*.lean\"):
  txt=p.read_text(errors=\"replace\")
  for d in extract_declarations(txt,library=\"AJCR\",file=str(p.relative_to(T/tag))):
   pre,res=split_top(d.signature); n=pre.count(\".RepresentableBy\")
   out[d.name]=(n, \".RepresentableBy\" in res, d.file, d.line, \" \".join(d.signature.split()))
 return out
b=load(\"base\");h=load(\"head\")
print(\"ADDED_INPUT_DECLS\")
for name in sorted(h.keys()-b.keys()):
 n,res,file,line,sig=h[name]
 if n: print(f\"{n}\\t{int(res)}\\t{name}\\t{file}:{line}\\t{sig}\")
print(\"CHANGED_INPUT_DECLS\")
for name in sorted(h.keys()&b.keys()):
 if h[name][0]"'!=b[name][0]:
  print(name,b[name][0],"->",h[name][0],h[name][2],h[name][3])
print("REMOVED_INPUT_DECLS")
for name in sorted(b.keys()-h.keys()):
 n,res,file,line,sig=b[name]
 if n: print(n,name,file,line)
print("ADDED_RESULT_CONSUMERS")
for name in sorted(h.keys()-b.keys()):
 n,res,file,line,sig=h[name]
 if n and res: print(name,file,line)
PY
'

